 1	import type { IncomingMessage, ServerResponse } from 'node:http';
 2	import type { Router } from '../router.js';
 3	import type { AppConfig, GitCredentialEntry } from '../../config/config.types.js';
 4	import type { PollingManager } from '../pollingManager.js';
 5	import type { ErrorLogManager } from '../../error-log/error-log.manager.js';
 6	import { saveConfigField } from '../../config/config.js';
 7	import { parseJsonBody, sendJson, sendError, isPlainObject } from '../requestUtils.js';
 8	import { toKebabCase } from '../../utils/slug.js';
 9	
10	// Polling-interval bounds — shared with settings UI (gui/public/js/views/settings.js).
11	import {
12	    MIN_POLLING_INTERVAL_SECONDS,
13	    MAX_POLLING_INTERVAL_SECONDS,
14	    MIN_NOTES_CARD_HEIGHT,
15	    MAX_NOTES_CARD_HEIGHT,
16	    MIN_NOTES_COLUMNS,
17	    MAX_NOTES_COLUMNS,
18	} from '../../config/config.constants.js';
19	
20	// ---------------------------------------------------------------------------
21	// Helpers
22	// ---------------------------------------------------------------------------
23	
24	/**
25	 * Masks a credential token for display in API responses.
26	 * Shows the last 4 characters of the token prefixed with `****`.
27	 * Tokens shorter than 4 characters are fully masked as `****`.
28	 */
29	function maskToken(token: string): string {
30	    return token.length < 4 ? '****' : '****' + token.slice(-4);
31	}
32	
33	/**
34	 * Extracts and lowercases the scheme from a URL string (the part before the
35	 * first `:`). Returns an empty string when no colon is present.
36	 *
37	 * @example extractScheme('https://example.com') // → 'https'
38	 * @example extractScheme('javascript:alert(1)') // → 'javascript'
39	 */
40	function extractScheme(url: string): string {
41	    const colonIdx = url.indexOf(':');
42	    return colonIdx !== -1 ? url.slice(0, colonIdx).toLowerCase() : '';
43	}
44	
45	/**
46	 * Type guard that returns `true` when `value` is a finite integer number.
47	 * Used by PUT route handlers to validate numeric config fields.
48	 *
49	 * @param value - The value to test (any type accepted).
50	 * @returns `true` when `value` is of type `number`, finite, and an integer; `false` otherwise.

151	 * | GET    | /api/config/webserver-url    | Return current `webserverUrl` (or null)  |
152	 * | PUT    | /api/config/webserver-url    | Update the webserver URL                 |
153	 *
154	 * **Notes display endpoints:**
155	 *
156	 * | Method | Path                          | Description                                                                                                         |
157	 * |--------|-------------------------------|---------------------------------------------------------------------------------------------------------------------|
158	 * | GET    | /api/config/notes-display     | Return current `notesCardHeight` and `notesColumns`                                                                 |
159	 * | PUT    | /api/config/notes-display     | Update notes display settings (partial updates — all fields optional). Fields: `notesCardHeight` ∈ [120, 800] (integer px), `notesColumns` ∈ [1, 6] (integer) |
160	 *
161	 * Changes take effect immediately (the in-memory `appConfig` is mutated) and
162	 * are persisted to `config.json` via `saveConfigField()`.
163	 *
164	 * **Security:** tokens are never returned in full — only the last 4 characters
165	 * are exposed. The `host` field accepts any non-empty string (no format
166	 * restriction is enforced at this layer).
167	 *
168	 * @param options - Named-options bag: `router`, `appConfig`, optional
169	 *   `configPath` (defaults to tool-root `config.json`), optional
170	 *   `pollingManager` (restarts polling loop when present).
171	 */
172	export function registerConfigRoutes(options: ConfigRoutesOptions): void {
173	    const { router, appConfig, configPath, pollingManager, errorLogManager } = options;
174	    // ------------------------------------------------------------------
175	    // GET /api/config/credentials — list all (tokens masked)
176	    // Returns GitCredentialEntry[] with tokens masked.
177	    // ------------------------------------------------------------------
178	    router.get('/api/config/credentials', (
179	        _req: IncomingMessage,
180	        res: ServerResponse,
181	        _params: Record<string, string>,
182	    ): void => {
183	        sendJson(res, 200, buildMaskedCredentials(appConfig.gitCredentials));
184	    });
185	
186	    // ------------------------------------------------------------------
187	    // PUT /api/config/credentials — add or update a single entry
188	    //
189	    // Request body: { id?: string, label: string, host: string, token: string }
190	    //
191	    // - When `id` is omitted: auto-generates a kebab-case ID from `label`,
192	    //   appending a numeric suffix (-2, -3, …) if needed to avoid collisions.
193	    //   Always creates a new entry.
194	    // - When `id` is provided and matches an existing entry: upserts (replaces)
195	    //   the existing entry in-place.
196	    // - When `id` is provided and does NOT match any existing entry: creates a
197	    //   new entry with the given ID (after checking the ID is not already taken).
198	    //
199	    // Returns 400 when the resulting ID would collide with an existing entry
200	    // that is NOT the one being updated (duplicate-ID rejection).
201	    // ------------------------------------------------------------------
202	    router.put('/api/config/credentials', async (
203	        req: IncomingMessage,
204	        res: ServerResponse,
205	        _params: Record<string, string>,
206	    ): Promise<void> => {
207	        let body: unknown;
208	        try {
209	            body = await parseJsonBody(req);
210	        } catch (err) {
211	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
212	            return;
213	        }
214	
215	        if (!isPlainObject(body)) {
216	            sendError(res, 400, 'Request body must be a JSON object.');
217	            return;
